"use client";

import { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  Globe, 
  GraduationCap, 
  Sparkles, 
  Plus, 
  Loader2, 
  Target, 
  Users, 
  Clock, 
  ArrowRight,
  LayoutDashboard,
  Settings,
  MessageSquare,
  Zap
} from 'lucide-react';
import { ClassroomRadar } from '@/components/teacher/ClassroomRadar';
import { useSDGStore } from '@/services/storage/sdg-store';
import { firebaseService } from '@/services/firebase/firebase-service';
import { geminiService } from '@/services/ai/gemini-service';

export default function TeacherDashboard() {
  const [courseTitle, setCourseTitle] = useState('');
  const [loading, setLoading] = useState(false);
  const { currentRoadmap, setRoadmap } = useSDGStore();

  const handleGenerate = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!courseTitle.trim()) return;
    
    setLoading(true);
    try {
      const result = await geminiService.generateRoadmap(courseTitle);
      setRoadmap(result);
      await firebaseService.pushRoadmap('global-class', result);
    } catch (error) {
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  const roadmap = currentRoadmap;

  return (
    <div className="min-h-screen bg-slate-950 text-white font-sans selection:bg-emerald-500/30 overflow-hidden relative">
      
      {/* Background Decor */}
      <div className="absolute top-0 right-0 w-1/2 h-screen bg-emerald-600/5 blur-[120px] pointer-events-none" />
      <div className="absolute bottom-0 left-0 w-1/3 h-1/2 bg-blue-600/5 blur-[100px] pointer-events-none" />
      
      <nav className="h-24 px-12 flex items-center justify-between border-b border-white/5 bg-slate-950/50 backdrop-blur-xl relative z-20">
        <div className="flex items-center space-x-4">
          <div className="w-10 h-10 bg-emerald-600 rounded-xl flex items-center justify-center">
            <GraduationCap className="w-6 h-6 text-white" />
          </div>
          <div>
            <h1 className="text-sm font-black uppercase tracking-tighter italic">Teacher Architect</h1>
            <p className="text-[9px] font-black uppercase text-emerald-500 tracking-widest">Sustain-Ability AI OS</p>
          </div>
        </div>

        <div className="flex items-center space-x-8">
           <div className="flex items-center space-x-3 px-4 py-2 bg-white/5 rounded-full border border-white/10">
              <Users className="w-3 h-3 text-slate-400" />
              <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">22 Active Students</span>
           </div>
           <button className="text-[10px] font-black uppercase tracking-widest text-slate-500 hover:text-white transition-all">Settings</button>
        </div>
      </nav>

      <div className="flex">
        {/* Sidebar */}
        <aside className="w-20 lg:w-64 h-[calc(100vh-96px)] border-r border-white/5 bg-slate-950/30 p-4 space-y-4 relative z-20">
          <button className="w-full h-12 rounded-2xl bg-emerald-600/10 text-emerald-500 flex items-center justify-center lg:justify-start lg:px-4 space-x-3 transition-all">
            <LayoutDashboard className="w-5 h-5 shrink-0" />
            <span className="hidden lg:block text-[10px] font-black uppercase tracking-widest">Architect</span>
          </button>
          <button className="w-full h-12 rounded-2xl text-slate-500 flex items-center justify-center lg:justify-start lg:px-4 space-x-3 transition-all hover:bg-white/5">
            <MessageSquare className="w-5 h-5 shrink-0" />
            <span className="hidden lg:block text-[10px] font-black uppercase tracking-widest">Classroom</span>
          </button>
          <button className="w-full h-12 rounded-2xl text-slate-500 flex items-center justify-center lg:justify-start lg:px-4 space-x-3 transition-all hover:bg-white/5">
            <Settings className="w-5 h-5 shrink-0" />
            <span className="hidden lg:block text-[10px] font-black uppercase tracking-widest">Settings</span>
          </button>
        </aside>

        {/* Main Content */}
        <main className="flex-1 max-w-[1600px] mx-auto grid grid-cols-1 lg:grid-cols-12 gap-12 p-12 relative z-10 overflow-y-auto h-[calc(100vh-96px)]">
          
          {/* Left Column: Roadmap Architect */}
          <section className="lg:col-span-8 space-y-12">
            
            <header className="space-y-4">
              <div className="inline-flex items-center space-x-2 px-3 py-1 bg-emerald-600/10 border border-emerald-500/20 rounded-full">
                <Zap className="w-3 h-3 text-emerald-500" />
                <span className="text-[8px] font-black uppercase tracking-widest text-emerald-500">Generative Logic Engine v4</span>
              </div>
              <h2 className="text-5xl font-black tracking-tighter uppercase italic leading-none">Curriculum <span className="text-emerald-500">Architect.</span></h2>
              <p className="text-[10px] font-bold uppercase tracking-widest text-slate-500">Manifest complex SDG roadmaps through AI-driven modular synthesis.</p>
            </header>

            <div className="p-12 bg-slate-900 border border-white/5 rounded-[4rem] space-y-8 backdrop-blur-sm shadow-2xl">
              <div className="space-y-4">
                <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 ml-2">Course Domain Artifact</label>
                <div className="flex space-x-4">
                  <input 
                    type="text" 
                    value={courseTitle}
                    onChange={(e) => setCourseTitle(e.target.value)}
                    placeholder="e.g. Python for Climate Science"
                    className="flex-1 h-16 bg-slate-950 border border-white/10 rounded-2xl px-8 text-sm font-bold placeholder:text-slate-800 focus:outline-none focus:border-emerald-500/50 transition-all font-mono"
                  />
                  <button 
                    onClick={() => handleGenerate()}
                    disabled={loading || !courseTitle}
                    className="px-10 h-16 bg-white text-slate-950 rounded-2xl font-black uppercase text-[10px] tracking-widest hover:bg-emerald-400 transition-all flex items-center space-x-3 disabled:opacity-50"
                  >
                    {loading ? <Loader2 className="w-4 h-4 animate-spin" /> : <Sparkles className="w-4 h-4" />}
                    <span>Generate Artifact</span>
                  </button>
                </div>
              </div>

              <AnimatePresence>
                {roadmap && (
                  <motion.div 
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="space-y-8 pt-8 border-t border-white/5"
                  >
                    <div className="flex items-center justify-between">
                      <div className="space-y-1">
                        <div className="flex items-center space-x-2 text-emerald-500">
                          <Target className="w-4 h-4" />
                          <span className="text-[10px] font-black uppercase tracking-widest">Mapped SDG Target</span>
                        </div>
                        <h3 className="text-3xl font-black uppercase italic tracking-tighter text-white">{roadmap.primarySDG.name}</h3>
                      </div>
                      <div className="px-8 py-3 bg-emerald-600 text-white rounded-full text-xs font-black uppercase italic tracking-tighter shadow-xl shadow-emerald-500/20">
                        Goal {roadmap.primarySDG.id}
                      </div>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                      {roadmap.modules.map((mod, idx) => (
                        <div key={idx} className="p-8 bg-slate-950 border border-white/5 rounded-[2.5rem] space-y-4 group hover:border-emerald-500/30 transition-all">
                          <div className="w-10 h-10 rounded-2xl bg-emerald-600/10 flex items-center justify-center text-[10px] font-black text-emerald-500 border border-emerald-500/20">
                            M{idx + 1}
                          </div>
                          <h4 className="font-bold text-sm tracking-tight leading-snug min-h-[40px]">{mod.title}</h4>
                          <div className="flex items-center space-x-2 text-[8px] font-black uppercase tracking-[0.2em] text-slate-600">
                             <span>Instructional Node</span>
                             <div className="w-1 h-1 bg-emerald-500 rounded-full" />
                          </div>
                        </div>
                      ))}
                    </div>
                  </motion.div>
                )}
              </AnimatePresence>
            </div>
          </section>

          {/* Right Column: Classroom Radar */}
          <section className="lg:col-span-4 space-y-10">
             <header className="space-y-2">
              <h2 className="text-2xl font-black tracking-tighter uppercase italic">Classroom <span className="text-emerald-500">Radar.</span></h2>
              <p className="text-[9px] font-black uppercase tracking-widest text-slate-600 italic">Telemetry from the Student Sandbox.</p>
            </header>

            <div className="space-y-6">
              <ClassroomRadar />
              
              <div className="p-10 bg-slate-900 border border-white/5 rounded-[3rem] space-y-8 shadow-xl">
                 <div className="flex items-center justify-between">
                    <h3 className="text-[10px] font-black uppercase tracking-widest text-emerald-500">Live Feedback</h3>
                    <div className="w-2 h-2 bg-emerald-500 rounded-full animate-ping" />
                 </div>
                 <div className="space-y-6">
                    {[
                      { user: 'Student_01', msg: 'Deployed Module 1 Logic', time: '2m' },
                      { user: 'Student_04', msg: 'Requesting Clarification', time: '5m' },
                      { user: 'System', msg: 'Roadmap Manifested: SDG 13', time: '12m' },
                    ].map((log, i) => (
                      <div key={i} className="flex items-start space-x-4">
                        <div className="w-1 h-10 bg-emerald-500/20 rounded-full shrink-0" />
                        <div>
                          <p className="text-[11px] font-bold text-white leading-tight">{log.msg}</p>
                          <p className="text-[8px] font-black uppercase tracking-widest text-slate-600 mt-1">{log.user} • {log.time}</p>
                        </div>
                      </div>
                    ))}
                 </div>
              </div>
            </div>
          </section>
        </main>
      </div>
    </div>
  );
}
